-- =====================================================================
-- TÉCNICA · FASE 1 · DESCARGAS DE DISTRIBUCIÓN · 80 — VERIFICACIÓN DE SOLO LECTURA (una sola consulta; apta para el editor SQL web).
-- Todas las filas deben decir OK. Nota: después de este paquete, la fila de la huella del conjunto de la verificación del aviso por contrato deja de valer.
-- =====================================================================
select k, v from (
  select 1 as o, '01 las 4 RPC: security definer, search_path fijo, solo service_role' as k,
         case when (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['geoportal_redes_reporte_iniciar', 'geoportal_redes_reporte_pagina', 'geoportal_redes_reporte_cerrar', 'geoportal_redes_reporte_sectores']) and p.prosecdef and p.proconfig is not null
                     and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute')
                     and not exists (select 1 from aclexplode(p.proacl) x where x.grantee = 0)) = 4 then 'OK' else 'MAL' end as v
  union all select 2, '02 ninguna función interna de redes la ejecuta la API',
         case when not exists (select 1 from pg_proc p where p.pronamespace = 'redes'::regnamespace
                                and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute') or has_function_privilege('service_role', p.oid, 'execute'))) then 'OK' else 'MAL' end
  union all select 3, '03 huellas md5 de las 24 nuevas y del conjunto de funciones de redes',
         case when (select count(*) from (values ('geoportal_redes_reporte_cerrar(text,bigint,integer,text,text)', '875ac07e496368d8947c5c803d658dc7'), ('geoportal_redes_reporte_iniciar(text,text,jsonb,text,boolean,text)', '05ee00808781f3af88db3d3a57c68f22'), ('geoportal_redes_reporte_pagina(text,bigint,text,integer)', '5e55735ae8f7ad024627f1393aedefdd'), ('geoportal_redes_reporte_sectores(text)', 'b4c7e051d0f41881fc24550a7297f538'), ('redes.f_rep_activos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '4e4f663f97dfebb12cdf2fbb04cfb962'), ('redes.f_rep_bot(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'b697931e9e7276348453bfa9bf95fce8'), ('redes.f_rep_catalogo()', '467a1941f5fc3583e9d3b6c149507ea7'), ('redes.f_rep_col(text,text,text,text,integer)', 'cf16ae8bdb29a755236e8098b3e4f8a6'), ('redes.f_rep_columnas(text)', '73f3fbcf2bbcf893e980783226e53031'), ('redes.f_rep_contar(text,jsonb,boolean,timestamp with time zone)', 'c0926aff859accf709ee59e56fb4d5f1'), ('redes.f_rep_eventos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '8c6565348cac64d2bf1c21b825698024'), ('redes.f_rep_filas(text,jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'e85f272201e12b9108b85cac8d748e27'), ('redes.f_rep_filtros(text,jsonb)', 'a489aebec61be91f4067dfeb7a44e282'), ('redes.f_rep_l116(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'd2962cd4520396f2c0616985bfa8238f'), ('redes.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '9ec53194c4550a39509601d9bcfe374f'), ('redes.f_rep_levantamientos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '2902d431c7c572543d80dc9f2bb6d0cd'), ('redes.f_rep_max_filas()', '64e8b7852af79a4b9983fec4edbc7aee'), ('redes.f_rep_punto(geometry)', '5701c68467a8dd5e738b91b89a8ef84d'), ('redes.f_rep_rotulo(text)', 'c837dc6b2d58acff6f3e96425a93347d'), ('redes.f_rep_sector_geom(text)', 'd5b7e0f1d06fe647a72027d79371c13f'), ('redes.f_rep_sectores()', '05ea25483d5802359f996edbefeb0bb5'), ('redes.f_rep_sensibles(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'cf2ab4f51d82ad171c80f85834a748df'), ('redes.f_rep_ts(timestamp with time zone)', '95b328ce9d7272918dd1614790216b4d'), ('redes.f_rep_valvulas(jsonb,timestamp with time zone,text,integer,boolean)', '25054a9098b30fd5fa94a41bc215a44b')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 24
               and (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
                     where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) = '3f3c89e603629d92e1cc5065de33d0c1' then 'OK' else 'MAL' end
  union all select 4, '04 pg-safeupdate: ninguna función con DELETE o UPDATE sin WHERE',
         coalesce((select 'MAL: ' || string_agg(distinct funcion, ', ') from redes.f_funciones_sin_where()), 'OK')
  union all select 5, '05 no se tocó nada de lo publicado que se lee ni las rutas del bot de nombre parecido (supervisor, perfil, sector, reportes de un evento, descarga de daños e intervenciones, reporte_convertir y reporte_descartar)',
         case when (select count(*) from (values ('redes.f_supervisor(text,text)', 'da1844d42f25ce4ba6abeebe207869b3'), ('redes.f_perfil_lectura(text)', 'b16cdc53435687d24704b0af7770b0ff'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('public.geoportal_redes_descarga(text,text,date,date,boolean,text)', '6a45b63d76ee2e96d68439a14f238c1f'), ('public.geoportal_redes_reporte_convertir(text,uuid,jsonb)', 'c51e28695635e028403f0c85c7ded5f9'), ('public.geoportal_redes_reporte_descartar(text,uuid,text)', 'f070fb817ea878564a0274154ce5c042')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 7 then 'OK' else 'MAL' end
  union all select 6, '06 las 2 tablas nuevas: RLS, solo inserción y sin permisos para la API',
         case when (select count(*) from pg_class c where c.oid in ('redes.reporte_descargas'::regclass, 'redes.reporte_descarga_cierres'::regclass) and c.relrowsecurity
                     and not has_table_privilege('anon', c.oid, 'select') and not has_table_privilege('authenticated', c.oid, 'select') and not has_table_privilege('service_role', c.oid, 'select')
                     and (select count(*) from pg_trigger t where t.tgrelid = c.oid and t.tgname in ('t_solo_agregar', 't_solo_agregar_trunc')) = 2) = 2 then 'OK' else 'MAL' end
  union all select 7, 'INFO descargas iniciadas · cerradas', (select count(*) from redes.reporte_descargas) || ' · ' || (select count(*) from redes.reporte_descarga_cierres)
) t order by o;
